const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>GradeAxis \u2014 Free GPA & CGPA Calculator (4.0, 5.0, 10.0 & German Scales)</title>\n<meta name=\"description\" content=\"GradeAxis is a free GPA calculator supporting 4.0, 5.0, 10.0 (Indian CGPA) and German 1.0\u20135.0 scales. Add courses, track semesters, plan your target CGPA. Unlimited free usage, no signup.\">\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<style>\n  body{ font-family: ui-sans-serif, system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif; background:#F7F4EA; color:#1F2937; }\n  .serif{ font-family: Georgia, \"Times New Roman\", serif; }\n  .report-card{ background:#FFFDF7; border:3px double #1E3A8A; box-shadow: 0 10px 30px rgba(30,58,138,.10); }\n  .rule-double{ border-top:3px double #1E3A8A; }\n  .rule-single{ border-top:1px solid #1E3A8A; }\n  .stamp{ border:2px solid #B91C1C; color:#B91C1C; transform: rotate(-4deg); }\n  .scale-tab{ border:2px solid #1E3A8A; color:#1E3A8A; background:#fff; }\n  .scale-tab.active{ background:#1E3A8A; color:#F7F4EA; }\n  input[type=number]::-webkit-inner-spin-button{ opacity:1; }\n  select, input[type=text], input[type=number]{ background:#fff; }\n  select:focus, input:focus, button:focus-visible{ outline:2px solid #B91C1C; outline-offset:1px; }\n  .faq-item summary{ cursor:pointer; }\n  .faq-item summary::-webkit-details-marker{ display:none; }\n  @media print{\n    .no-print{ display:none !important; }\n    body{ background:#fff; }\n    .report-card{ box-shadow:none; }\n  }\n</style>\n</head>\n<body id=\"top\" class=\"min-h-screen\">\n\n<!-- Sticky header -->\n<header class=\"no-print sticky top-0 z-40 border-b-[3px] border-double\" style=\"border-color:#1E3A8A; background:#F7F4EA;\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 h-16 flex items-center justify-between\">\n    <a href=\"#top\" class=\"serif text-2xl font-bold tracking-tight\" style=\"color:#1E3A8A;\">Grade<span style=\"color:#B91C1C;\">Axis</span></a>\n    <nav class=\"flex items-center gap-5 text-sm font-semibold\" style=\"color:#1E3A8A;\">\n      <a href=\"#top\" class=\"hover:underline\">Home</a>\n      <a href=\"https://fixoraa.tech\" class=\"hover:underline\">More Tools</a>\n    </nav>\n  </div>\n</header>\n\n<!-- Hero -->\n<section class=\"mx-auto max-w-6xl px-4 sm:px-6 pt-10 pb-2 text-center\">\n  <p class=\"text-[11px] tracking-[0.3em] uppercase font-semibold\" style=\"color:#B91C1C;\">Official Academic Worksheet</p>\n  <h1 class=\"serif text-4xl sm:text-5xl font-bold mt-2\" style=\"color:#1E3A8A;\">GradeAxis</h1>\n  <p class=\"serif italic text-lg mt-1\" style=\"color:#1F2937;\">GPA &amp; CGPA Calculator \u2014 every scale, one report card</p>\n  <div class=\"mt-4 flex items-center justify-center gap-3 flex-wrap\">\n    <span class=\"inline-flex items-center gap-1.5 text-xs font-bold uppercase tracking-wider px-3 py-1.5 rounded-full border-2\" style=\"border-color:#B91C1C; color:#B91C1C; background:#fff;\">\n      <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"><path d=\"M13 2L3 14h7l-1 8 10-12h-7l1-8z\"/></svg>\n      Unlimited Free Usage\n    </span>\n    <span class=\"text-xs font-semibold px-3 py-1.5 rounded-full\" style=\"background:#1E3A8A; color:#F7F4EA;\">No signup &middot; No paywall &middot; No watermark</span>\n  </div>\n  <p class=\"mt-4 max-w-2xl mx-auto text-sm leading-relaxed\" style=\"color:#4B5563;\">\n    Enter your courses below and GradeAxis computes your semester GPA instantly \u2014 on the US 4.0 scale,\n    the 5.0 scale, the Indian 10.0 CGPA scale, or the inverted German 1.0\u20135.0 scale. Save semesters to your\n    personal ledger, watch your cumulative CGPA grow, and use the planner to see exactly what grades you need\n    to hit your target. Everything runs in your browser; your data never leaves your device.\n  </p>\n</section>\n\n<!-- TOP AD -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pt-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <div class=\"origin-top scale-[0.44] sm:scale-100 shrink-0\">\n        <script>\n          atOptions = { 'key' : '4e68ac77881c17fe128a46565d9a4e8c', 'format' : 'iframe', 'height' : 90, 'width' : 728, 'params' : {} };\n        </script>\n        <script src=\"https://www.highrevenueformat.com/4e68ac77881c17fe128a46565d9a4e8c/invoke.js\"></script>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ============ TOOL ============ -->\n<main class=\"mx-auto max-w-6xl px-4 sm:px-6 py-6\">\n<div class=\"report-card rounded-sm p-4 sm:p-8\">\n\n  <!-- Report card masthead -->\n  <div class=\"flex flex-wrap items-start justify-between gap-4 pb-4\">\n    <div>\n      <p class=\"text-[10px] tracking-[0.25em] uppercase font-bold\" style=\"color:#B91C1C;\">GradeAxis &middot; Form GA-2026</p>\n      <h2 class=\"serif text-2xl sm:text-3xl font-bold\" style=\"color:#1E3A8A;\">Semester Worksheet &amp; Academic Ledger</h2>\n      <p class=\"text-xs mt-1\" style=\"color:#6B7280;\">All calculations are performed locally in your browser. Print this page for a clean report.</p>\n    </div>\n    <div class=\"stamp serif text-xs font-bold uppercase tracking-widest px-3 py-2 rounded-sm\">Verified<br>Math</div>\n  </div>\n  <div class=\"rule-double mb-6\"></div>\n\n  <!-- 1. Scale selector -->\n  <section aria-label=\"Grading scale\">\n    <h3 class=\"serif text-lg font-bold mb-2\" style=\"color:#1E3A8A;\">1 &middot; Choose your grading scale</h3>\n    <div id=\"scaleTabs\" class=\"flex flex-wrap gap-2\" role=\"tablist\" aria-label=\"Grading scale options\">\n      <button type=\"button\" data-scale=\"4.0\" class=\"scale-tab active serif text-sm font-bold px-4 py-2 rounded-sm\">4.0 &middot; US</button>\n      <button type=\"button\" data-scale=\"5.0\" class=\"scale-tab serif text-sm font-bold px-4 py-2 rounded-sm\">5.0 scale</button>\n      <button type=\"button\" data-scale=\"10.0\" class=\"scale-tab serif text-sm font-bold px-4 py-2 rounded-sm\">10.0 &middot; Indian CGPA</button>\n      <button type=\"button\" data-scale=\"german\" class=\"scale-tab serif text-sm font-bold px-4 py-2 rounded-sm\">German 1.0\u20135.0</button>\n    </div>\n    <p id=\"scaleNote\" class=\"text-xs mt-2 italic\" style=\"color:#6B7280;\"></p>\n    <label class=\"mt-3 inline-flex items-center gap-2 text-sm font-semibold cursor-pointer select-none\" style=\"color:#1F2937;\">\n      <input id=\"weightedToggle\" type=\"checkbox\" class=\"w-4 h-4 accent-[#B91C1C]\">\n      Weighted GPA \u2014 Honors courses +0.5, AP/IB courses +1.0\n      <span class=\"text-xs font-normal\" style=\"color:#6B7280;\">(German scale: \u22120.5 / \u22121.0, lower is better)</span>\n    </label>\n  </section>\n\n  <div class=\"rule-single my-6\"></div>\n\n  <!-- 2. Course table -->\n  <section aria-label=\"Courses\">\n    <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n      <h3 class=\"serif text-lg font-bold\" style=\"color:#1E3A8A;\">2 &middot; Enter your courses</h3>\n      <div class=\"flex gap-2\">\n        <button id=\"addCourse\" type=\"button\" class=\"text-sm font-bold px-4 py-2 rounded-sm text-white\" style=\"background:#B91C1C;\">+ Add course</button>\n        <button id=\"clearCourses\" type=\"button\" class=\"text-sm font-semibold px-4 py-2 rounded-sm border-2\" style=\"border-color:#1E3A8A; color:#1E3A8A;\">Clear</button>\n      </div>\n    </div>\n    <div class=\"hidden md:grid grid-cols-12 gap-2 text-[11px] font-bold uppercase tracking-wider mb-1 px-1\" style=\"color:#1E3A8A;\">\n      <div class=\"col-span-4\">Course name</div><div class=\"col-span-2\">Credits</div><div class=\"col-span-2\">Grade</div>\n      <div class=\"col-span-2\">Level</div><div class=\"col-span-1 text-right\">Points</div><div class=\"col-span-1\"></div>\n    </div>\n    <div id=\"courseRows\" class=\"space-y-2\"></div>\n    <p class=\"text-xs mt-2\" style=\"color:#6B7280;\">Tip: rows with missing grades or zero credits are ignored in the math. Grade F always counts as 0 points (5.0 on the German scale), even in weighted mode.</p>\n  </section>\n\n  <div class=\"rule-single my-6\"></div>\n\n  <!-- 3. Semester result -->\n  <section aria-label=\"Semester GPA result\">\n    <h3 class=\"serif text-lg font-bold mb-3\" style=\"color:#1E3A8A;\">3 &middot; Semester result</h3>\n    <div class=\"grid md:grid-cols-2 gap-6 items-center\">\n      <div id=\"gpaDial\" class=\"flex justify-center\" role=\"img\" aria-label=\"GPA dial\"></div>\n      <div class=\"grid grid-cols-2 gap-3\">\n        <div class=\"border rounded-sm p-4 text-center\" style=\"border-color:#1E3A8A; background:#F7F4EA;\">\n          <p class=\"text-[10px] uppercase tracking-widest font-bold\" style=\"color:#6B7280;\">Semester GPA</p>\n          <p id=\"statGpa\" class=\"serif text-4xl font-bold\" style=\"color:#1E3A8A;\">&mdash;</p>\n        </div>\n        <div class=\"border rounded-sm p-4 text-center\" style=\"border-color:#1E3A8A; background:#F7F4EA;\">\n          <p class=\"text-[10px] uppercase tracking-widest font-bold\" style=\"color:#6B7280;\">Letter</p>\n          <p id=\"statLetter\" class=\"serif text-4xl font-bold\" style=\"color:#B91C1C;\">&mdash;</p>\n        </div>\n        <div class=\"border rounded-sm p-4 text-center\" style=\"border-color:#1E3A8A; background:#F7F4EA;\">\n          <p class=\"text-[10px] uppercase tracking-widest font-bold\" style=\"color:#6B7280;\">Total credits</p>\n          <p id=\"statCredits\" class=\"serif text-4xl font-bold\" style=\"color:#1F2937;\">&mdash;</p>\n        </div>\n        <div class=\"border rounded-sm p-4 text-center\" style=\"border-color:#1E3A8A; background:#F7F4EA;\">\n          <p class=\"text-[10px] uppercase tracking-widest font-bold\" style=\"color:#6B7280;\">Quality points</p>\n          <p id=\"statPoints\" class=\"serif text-4xl font-bold\" style=\"color:#1F2937;\">&mdash;</p>\n        </div>\n      </div>\n    </div>\n    <p class=\"serif italic text-sm mt-3 text-center\" style=\"color:#6B7280;\">GPA = &sum;(grade points &times; credits) &divide; &sum;(credits)</p>\n  </section>\n\n  <div class=\"rule-single my-6\"></div>\n\n  <!-- 4. Semester ledger -->\n  <section aria-label=\"Semester history ledger\">\n    <h3 class=\"serif text-lg font-bold mb-2\" style=\"color:#1E3A8A;\">4 &middot; Semester ledger \u2014 cumulative CGPA tracker</h3>\n    <p class=\"text-xs mb-3\" style=\"color:#6B7280;\">Save each finished semester below. Your ledger is stored privately in this browser (localStorage) and your cumulative CGPA updates automatically.</p>\n    <div class=\"flex flex-col sm:flex-row gap-2 mb-4\">\n      <input id=\"semName\" type=\"text\" maxlength=\"60\" placeholder=\"Semester name, e.g. Fall 2026 \u2014 Semester 3\"\n        class=\"flex-1 border-2 rounded-sm px-3 py-2 text-sm\" style=\"border-color:#1E3A8A;\">\n      <button id=\"saveSemester\" type=\"button\" class=\"text-sm font-bold px-5 py-2 rounded-sm text-white\" style=\"background:#1E3A8A;\">Save semester to ledger</button>\n    </div>\n    <p id=\"ledgerMsg\" class=\"text-xs mb-3 font-semibold\" style=\"color:#B91C1C;\"></p>\n    <div class=\"grid sm:grid-cols-2 gap-3 mb-4\">\n      <div class=\"border-2 rounded-sm p-4 text-center\" style=\"border-color:#1E3A8A; background:#1E3A8A;\">\n        <p class=\"text-[10px] uppercase tracking-widest font-bold\" style=\"color:#F7F4EA;\">Cumulative CGPA (saved semesters)</p>\n        <p id=\"statCgpa\" class=\"serif text-4xl font-bold\" style=\"color:#F7F4EA;\">&mdash;</p>\n        <p id=\"statCgpaSub\" class=\"text-xs mt-1\" style=\"color:#D1D5DB;\"></p>\n      </div>\n      <div class=\"border-2 rounded-sm p-4 text-center\" style=\"border-color:#B91C1C; background:#fff;\">\n        <p class=\"text-[10px] uppercase tracking-widest font-bold\" style=\"color:#B91C1C;\">Projected CGPA (incl. current worksheet)</p>\n        <p id=\"statProj\" class=\"serif text-4xl font-bold\" style=\"color:#B91C1C;\">&mdash;</p>\n        <p id=\"statProjSub\" class=\"text-xs mt-1\" style=\"color:#6B7280;\"></p>\n      </div>\n    </div>\n    <div class=\"overflow-x-auto\">\n      <table class=\"w-full text-sm border\" style=\"border-color:#1E3A8A;\">\n        <thead><tr class=\"text-left text-[11px] uppercase tracking-wider\" style=\"background:#1E3A8A; color:#F7F4EA;\">\n          <th class=\"px-3 py-2 font-bold\">Semester</th><th class=\"px-3 py-2 font-bold\">Scale</th>\n          <th class=\"px-3 py-2 font-bold text-right\">GPA</th><th class=\"px-3 py-2 font-bold text-right\">Credits</th>\n          <th class=\"px-3 py-2 font-bold text-right\">Points</th><th class=\"px-3 py-2\"></th>\n        </tr></thead>\n        <tbody id=\"ledgerBody\"></tbody>\n      </table>\n    </div>\n    <div class=\"flex flex-wrap gap-2 mt-3\">\n      <button id=\"downloadCsv\" type=\"button\" class=\"text-xs font-bold px-4 py-2 rounded-sm border-2\" style=\"border-color:#1E3A8A; color:#1E3A8A;\">Download ledger (CSV)</button>\n      <button id=\"clearLedger\" type=\"button\" class=\"text-xs font-semibold px-4 py-2 rounded-sm border\" style=\"border-color:#9CA3AF; color:#6B7280;\">Clear ledger</button>\n      <button id=\"printReport\" type=\"button\" class=\"no-print text-xs font-semibold px-4 py-2 rounded-sm border\" style=\"border-color:#9CA3AF; color:#6B7280;\">Print report card</button>\n    </div>\n  </section>\n\n  <div class=\"rule-single my-6\"></div>\n\n  <!-- 5. Planner -->\n  <section aria-label=\"GPA planner\">\n    <h3 class=\"serif text-lg font-bold mb-2\" style=\"color:#1E3A8A;\">5 &middot; Target planner \u2014 what grades do you need?</h3>\n    <p class=\"text-xs mb-3\" style=\"color:#6B7280;\">Enter your current standing and your goal. GradeAxis computes the average grade you must earn in your remaining credits, with an honest feasibility verdict.</p>\n    <div class=\"grid grid-cols-2 md:grid-cols-4 gap-3 mb-4\">\n      <label class=\"block\"><span class=\"text-xs font-bold uppercase tracking-wide\" style=\"color:#1E3A8A;\">Current CGPA</span>\n        <input id=\"plCur\" type=\"number\" step=\"0.01\" min=\"0\" placeholder=\"e.g. 3.10\" class=\"mt-1 w-full border-2 rounded-sm px-3 py-2 text-sm\" style=\"border-color:#1E3A8A;\"></label>\n      <label class=\"block\"><span class=\"text-xs font-bold uppercase tracking-wide\" style=\"color:#1E3A8A;\">Credits earned</span>\n        <input id=\"plEarned\" type=\"number\" step=\"1\" min=\"0\" placeholder=\"e.g. 45\" class=\"mt-1 w-full border-2 rounded-sm px-3 py-2 text-sm\" style=\"border-color:#1E3A8A;\"></label>\n      <label class=\"block\"><span class=\"text-xs font-bold uppercase tracking-wide\" style=\"color:#1E3A8A;\">Target CGPA</span>\n        <input id=\"plTarget\" type=\"number\" step=\"0.01\" min=\"0\" placeholder=\"e.g. 3.50\" class=\"mt-1 w-full border-2 rounded-sm px-3 py-2 text-sm\" style=\"border-color:#1E3A8A;\"></label>\n      <label class=\"block\"><span class=\"text-xs font-bold uppercase tracking-wide\" style=\"color:#1E3A8A;\">Credits remaining</span>\n        <input id=\"plRem\" type=\"number\" step=\"1\" min=\"1\" placeholder=\"e.g. 15\" class=\"mt-1 w-full border-2 rounded-sm px-3 py-2 text-sm\" style=\"border-color:#1E3A8A;\"></label>\n    </div>\n    <button id=\"planBtn\" type=\"button\" class=\"text-sm font-bold px-6 py-2.5 rounded-sm text-white\" style=\"background:#B91C1C;\">Calculate required grades</button>\n    <div id=\"planResult\" class=\"hidden mt-4 border-2 rounded-sm p-4\" style=\"border-color:#1E3A8A; background:#F7F4EA;\">\n      <div class=\"flex flex-wrap items-center gap-4\">\n        <div><p class=\"text-[10px] uppercase tracking-widest font-bold\" style=\"color:#6B7280;\">Required average</p>\n          <p class=\"serif text-3xl font-bold\" style=\"color:#1E3A8A;\"><span id=\"planReq\">&mdash;</span> <span id=\"planLetter\" class=\"text-xl\" style=\"color:#B91C1C;\"></span></p></div>\n        <div><p class=\"text-[10px] uppercase tracking-widest font-bold\" style=\"color:#6B7280;\">Verdict</p>\n          <p id=\"planVerdict\" class=\"text-sm font-bold px-3 py-1.5 rounded-full inline-block\"></p></div>\n      </div>\n      <p id=\"planDetail\" class=\"text-xs mt-2\" style=\"color:#4B5563;\"></p>\n      <p class=\"text-[11px] mt-2 italic\" style=\"color:#9CA3AF;\">Math: required = (target &times; total credits &minus; earned points) &divide; remaining credits.</p>\n    </div>\n  </section>\n\n  <div class=\"rule-single my-6\"></div>\n\n  <!-- 6. Conversion tables -->\n  <section aria-label=\"Conversion reference tables\">\n    <h3 class=\"serif text-lg font-bold mb-2\" style=\"color:#1E3A8A;\">6 &middot; Conversion reference \u2014 % &harr; letter &harr; grade points</h3>\n    <p class=\"text-xs mb-3\" style=\"color:#6B7280;\">Quick lookup tables. Percent bands are the widely used US-style cutoffs; Indian boards often use % &divide; 10 for CGPA, and German universities publish their own percent equivalents.</p>\n    <div id=\"convTables\" class=\"grid md:grid-cols-3 gap-4\"></div>\n    <ul class=\"text-xs mt-3 space-y-1 list-disc pl-5\" style=\"color:#4B5563;\">\n      <li><strong>Indian boards (CBSE-style):</strong> percentage &asymp; CGPA &times; 9.5. So a 9.0 CGPA &asymp; 85.5%.</li>\n      <li><strong>10-point universities:</strong> CGPA &asymp; percentage &divide; 10 (e.g. 82% &asymp; 8.2).</li>\n      <li><strong>German (TUM-style) conversion:</strong> German grade = 1 + 3 &times; (best grade &minus; your grade) &divide; (best grade &minus; lowest passing grade).</li>\n    </ul>\n  </section>\n\n  <div class=\"rule-double mt-6 pt-3 flex items-center justify-between\">\n    <p class=\"serif italic text-xs\" style=\"color:#6B7280;\">End of worksheet &mdash; GradeAxis</p>\n    <p class=\"serif text-xs font-bold\" style=\"color:#1E3A8A;\">Registrar&rsquo;s seal: GA &#10003;</p>\n  </div>\n</div>\n</main>\n\n<!-- BOTTOM AD -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pb-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <script async src=\"https://js.wpadmngr.com/static/adManager.js\" data-admpid=\"464498\"></script>\n    </div>\n  </div>\n</div>\n\n<!-- ============ SEO ARTICLE ============ -->\n<div class=\"mx-auto max-w-6xl px-4 sm:px-6 pb-10\">\n<article id=\"seo-article\" class=\"report-card rounded-sm p-6 sm:p-10\">\n  <p class=\"text-[11px] tracking-[0.25em] uppercase font-bold mb-2\" style=\"color:#B91C1C;\">GradeAxis Study Guide</p>\n  <h2 class=\"serif text-3xl font-bold mb-6\" style=\"color:#1E3A8A;\">The Complete Guide to Calculating GPA and CGPA on Every Major Scale</h2>\n\n  <h3 class=\"serif text-xl font-bold mt-8 mb-3\" style=\"color:#1E3A8A;\">What exactly is a GPA?</h3>\n  <p class=\"text-sm leading-7 mb-4\" style=\"color:#374151;\">A Grade Point Average (GPA) is a single number that summarizes your academic performance over a set of courses. Instead of listing every grade you earned, schools convert each letter grade into grade points, weight those points by the number of credits each course carries, and then average the result. The formula is beautifully simple: GPA equals the sum of grade points multiplied by credits, divided by the sum of credits. In symbols, GPA = &sum;(grade points &times; credits) &divide; &sum;(credits). Because credits act as weights, a four-credit core subject influences your GPA twice as much as a two-credit elective. This is the step students most often skip when they try to average their grades by hand, and it is the reason a poor grade in a heavy required course hurts far more than the same grade in a light elective.</p>\n  <p class=\"text-sm leading-7 mb-4\" style=\"color:#374151;\">The term SGPA (Semester Grade Point Average) means the GPA of one semester or term, while CGPA (Cumulative Grade Point Average) means the average across all semesters completed so far. Your CGPA is not the average of your SGPAs \u2014 it is the total quality points earned across every semester divided by the total credits attempted. Averaging SGPAs directly gives the wrong answer whenever semesters carry different credit loads, a mistake that quietly distorts many hand calculations.</p>\n\n  <h3 class=\"serif text-xl font-bold mt-8 mb-3\" style=\"color:#1E3A8A;\">How to calculate GPA step by step</h3>\n  <p class=\"text-sm leading-7 mb-4\" style=\"color:#374151;\">Let us walk through a concrete example on the standard US 4.0 scale. Suppose a student takes four courses: Calculus (4 credits, grade A), Physics (4 credits, grade B+), English (3 credits, grade A&minus;), and History (3 credits, grade B). First, convert each letter grade to points: A is 4.0, B+ is 3.3, A&minus; is 3.7, and B is 3.0. Next, multiply points by credits for each course: Calculus gives 4.0 &times; 4 = 16.0, Physics gives 3.3 &times; 4 = 13.2, English gives 3.7 &times; 3 = 11.1, and History gives 3.0 &times; 3 = 9.0. Add the quality points: 16.0 + 13.2 + 11.1 + 9.0 = 49.3. Add the credits: 4 + 4 + 3 + 3 = 14. Finally divide: 49.3 &divide; 14 = 3.52. The semester GPA is 3.52, which sits between B+ and A&minus;. GradeAxis performs exactly this arithmetic the moment you type, and it shows the per-course points so you can audit every line.</p>\n\n  <h3 class=\"serif text-xl font-bold mt-8 mb-3\" style=\"color:#1E3A8A;\">The 4.0 scale: the American standard</h3>\n  <p class=\"text-sm leading-7 mb-4\" style=\"color:#374151;\">The 4.0 scale dominates US high schools and universities. Its grade-point mapping is: A = 4.0, A&minus; = 3.7, B+ = 3.3, B = 3.0, B&minus; = 2.7, C+ = 2.3, C = 2.0, C&minus; = 1.7, D+ = 1.3, D = 1.0, and F = 0. Some schools drop the plus/minus refinements and use only whole letters, but the mapping above is the version most colleges expect when they ask for your GPA on a 4.0 scale. A 3.5 or higher is generally considered strong, and 3.7 or above is competitive at selective institutions. International students should note that many US universities recalculate foreign transcripts onto this scale themselves, so the number you compute is an estimate for planning rather than an official figure.</p>\n\n  <h3 class=\"serif text-xl font-bold mt-8 mb-3\" style=\"color:#1E3A8A;\">The 5.0 scale</h3>\n  <p class=\"text-sm leading-7 mb-4\" style=\"color:#374151;\">The 5.0 scale appears in several forms. In US high schools it is usually the weighted ceiling: regular courses follow the 4.0 mapping while AP and IB courses add a full point, so an A in AP Calculus counts as 5.0. In other countries, including parts of the Middle East, Nigeria, and some European institutions, the 5.0 scale is simply the native grading scale where A = 5.0, B = 4.0, C = 3.0, D = 2.0, and F = 0. GradeAxis supports the full plus/minus version: A = 5.0, A&minus; = 4.7, B+ = 4.3, B = 4.0, B&minus; = 3.7, C+ = 3.3, C = 3.0, C&minus; = 2.7, D+ = 2.3, D = 2.0, F = 0. If your school uses a 5.0 scale without plus/minus grades, just pick the whole letters and the math stays correct.</p>\n\n  <h3 class=\"serif text-xl font-bold mt-8 mb-3\" style=\"color:#1E3A8A;\">The Indian 10.0 CGPA scale</h3>\n  <p class=\"text-sm leading-7 mb-4\" style=\"color:#374151;\">India runs on a 10-point CGPA system at both school and university level, though the letter labels differ by board. CBSE schools historically used grades like A1 and A2, while universities such as Anna University, VTU, and SPPU use O (Outstanding) = 10, A+ = 9, A = 8, B+ = 7, B = 6, C = 5, D = 4, and F/U = 0. The SGPA for a semester is the credit-weighted average of these points, and the CGPA is the credit-weighted average across semesters \u2014 exactly the same structure as the US formula, only with a different point mapping. Two conversions matter constantly for Indian students. First, percentage to CGPA: many universities treat CGPA as roughly percentage divided by 10, so 82% is about 8.2. Second, CGPA to percentage for CBSE-style reporting: percentage &asymp; CGPA &times; 9.5, so a 9.0 CGPA is about 85.5%. Students applying abroad then face the 10-to-4 conversion, where there is no single official formula \u2014 credential evaluators weigh your institution, your rank, and your board, which is why GradeAxis shows letter-equivalent conversions as planning estimates and labels them honestly.</p>\n\n  <h3 class=\"serif text-xl font-bold mt-8 mb-3\" style=\"color:#1E3A8A;\">The German 1.0\u20135.0 scale: upside down by design</h3>\n  <p class=\"text-sm leading-7 mb-4\" style=\"color:#374151;\">Germany inverts the logic most students know: 1.0 is the best possible grade and 5.0 means fail. The official descriptors run from 1.0 (sehr gut, very good) through 2.0 (gut, good), 3.0 (befriedigend, satisfactory), and 4.0 (ausreichend, sufficient), down to 5.0 (nicht ausreichend, failed). Intermediate steps of 0.3 are standard \u2014 1.3, 1.7, 2.3, 2.7, 3.3, 3.7 \u2014 giving the familiar ladder A = 1.0, A&minus; = 1.3, B+ = 1.7, B = 2.0, B&minus; = 2.3, C+ = 2.7, C = 3.0, C&minus; = 3.3, D+ = 3.7, D = 4.0, F = 5.0. Because lower is better, averaging works the same way arithmetically but the interpretation flips: a 1.5 average is excellent, a 2.5 is respectable, and anything approaching 4.0 is a warning sign. German universities converting foreign grades often use the modified Bavarian formula \u2014 German grade = 1 + 3 &times; (best grade &minus; your grade) &divide; (best grade &minus; lowest passing grade) \u2014 which is why GradeAxis lists that formula in its reference section. If you are an Indian or American student eyeing a German master&rsquo;s program, computing your average on the German scale first saves you from misreading your own transcript.</p>\n\n  <h3 class=\"serif text-xl font-bold mt-8 mb-3\" style=\"color:#1E3A8A;\">Weighted vs. unweighted GPA</h3>\n  <p class=\"text-sm leading-7 mb-4\" style=\"color:#374151;\">An unweighted GPA treats every course equally: an A is 4.0 whether it came from regular English or AP Physics. A weighted GPA adds a rigor bonus \u2014 conventionally +0.5 for Honors courses and +1.0 for AP or IB courses \u2014 so an A in AP Calculus counts as 5.0. Colleges like to see both numbers: the unweighted GPA shows raw achievement, while the weighted GPA rewards students who challenged themselves. This is also why weighted GPAs can exceed 4.0, which confuses students the first time they see a 4.3 on a classmate&rsquo;s profile. Two caveats matter. First, weighting policies differ by school \u2014 some districts use +0.5 for AP instead of +1.0, and some do not weight at all \u2014 so always check your school&rsquo;s official policy before reporting a number. Second, a failing grade stays failing: an F earns 0 points even in an AP course, because no rigor bonus can rescue a course you did not pass. GradeAxis follows both conventions, and on the German scale it applies the mirror image (&minus;0.5 for Honors, &minus;1.0 for AP) since lower is better there.</p>\n\n  <h3 class=\"serif text-xl font-bold mt-8 mb-3\" style=\"color:#1E3A8A;\">GPA vs. CGPA: why the distinction matters</h3>\n  <p class=\"text-sm leading-7 mb-4\" style=\"color:#374151;\">Your semester GPA answers &ldquo;how did I do this term?&rdquo; while your CGPA answers &ldquo;how am I doing overall?&rdquo; The CGPA is the number on your degree, the one employers and graduate schools ask for, and the one scholarships hinge on. Because the CGPA pools every credit you have ever attempted, early semesters cast a long shadow: a weak first year requires many strong semesters to dilute, since each new semester is a smaller fraction of a growing total. The mathematics of recovery is unforgiving but clear. If you have completed 30 credits at a 2.8 and want a 3.2 by the time you reach 60 credits, the 30 remaining credits must average (3.2 &times; 60 &minus; 2.8 &times; 30) &divide; 30 = 3.6. That is the exact formula GradeAxis&rsquo;s planner uses, and it explains why setting realistic targets early beats heroic comebacks later. Tracking every semester in a ledger, as GradeAxis does locally in your browser, turns this abstract math into a visible trend you can actually steer.</p>\n\n  <h3 class=\"serif text-xl font-bold mt-8 mb-3\" style=\"color:#1E3A8A;\">Planning: what grades do you need for your target?</h3>\n  <p class=\"text-sm leading-7 mb-4\" style=\"color:#374151;\">Reverse-engineering your goal is one of the most useful calculations a student can do. Start with three numbers you already know: your current CGPA, the credits you have completed, and the credits you still have left. Pick a target CGPA. The required average for your remaining credits is (target &times; total credits &minus; current CGPA &times; completed credits) &divide; remaining credits. If the answer exceeds the maximum of your scale \u2014 above 4.0 on the US scale, below 1.0 on the German scale \u2014 the target is mathematically impossible, and no amount of effort changes arithmetic. If the answer sits just under the maximum, the goal is a stretch that demands near-perfect grades. If it sits near or below your current average, your existing pace will carry you there. The honest verdict matters more than the number: students who learn a target is impossible in October can adjust their plans, while students who discover it in May have lost a year. Run the planner at the start of every semester, not at the end.</p>\n\n  <h3 class=\"serif text-xl font-bold mt-8 mb-3\" style=\"color:#1E3A8A;\">Converting between percentage, letter grades, and GPA</h3>\n  <p class=\"text-sm leading-7 mb-4\" style=\"color:#374151;\">Three representations of the same performance circulate in education: percentages, letter grades, and grade points. The common US-style percent bands are A: 93\u2013100, A&minus;: 90\u201392, B+: 87\u201389, B: 83\u201386, B&minus;: 80\u201382, C+: 77\u201379, C: 73\u201376, C&minus;: 70\u201372, D+: 67\u201369, D: 65\u201366, and F: below 65. Indian 10-point bands typically run O: 90\u2013100, A+: 80\u201389, A: 70\u201379, B+: 60\u201369, B: 50\u201359, C: 40\u201349, D: 35\u201339, F: below 35, though individual universities publish their own tables. German percent equivalents are roughly 1.0: 95\u2013100 down through 4.0: 50\u201354, with anything below 50 a 5.0 fail. To convert, go through the letter grade: 88% is a B+, which is 3.3 on the 4.0 scale and 1.7 on the German scale. GradeAxis&rsquo;s reference tables lay all three columns side by side so you never have to guess, and the calculator converts any GPA value across scales through its letter equivalent.</p>\n\n  <h3 class=\"serif text-xl font-bold mt-8 mb-3\" style=\"color:#1E3A8A;\">Common GPA mistakes to avoid</h3>\n  <p class=\"text-sm leading-7 mb-4\" style=\"color:#374151;\">The most frequent error is averaging letter grades without credits \u2014 treating a 2-credit lab and a 4-credit core subject as equals. Next comes averaging SGPAs instead of pooling points and credits, which silently misstates the CGPA whenever semesters differ in size. Students also forget that retaken courses follow their institution&rsquo;s repeat policy: some schools replace the old grade, others average both attempts, and some count both. Transfer credits usually count toward degree requirements but not toward the GPA at the new institution. Pass/fail and audit courses carry no grade points and must be excluded from the denominator. Finally, mixing scales \u2014 averaging a 10-point CGPA with a 4.0 GPA \u2014 produces nonsense; convert everything to one scale first. A calculator that shows per-course points, like GradeAxis does, makes each of these errors visible before they propagate.</p>\n\n  <h3 class=\"serif text-xl font-bold mt-8 mb-3\" style=\"color:#1E3A8A;\">Why keep a semester ledger</h3>\n  <p class=\"text-sm leading-7 mb-4\" style=\"color:#374151;\">A GPA is a snapshot; a ledger is a story. Recording each semester&rsquo;s GPA, credits, and quality points in one place lets you see trends \u2014 a rising sophomore year, a overloaded junior fall \u2014 that a single number hides. It also makes the CGPA calculation auditable: instead of trusting a portal&rsquo;s black box, you can recompute your cumulative average from your own records. Because GradeAxis stores the ledger only in your browser&rsquo;s local storage, the record is private by construction: no account, no server, nothing to leak. Export it to CSV at the end of each term as a backup, print the report card for your files, and start each new semester with the planner so every term begins with a target instead of a surprise.</p>\n</article>\n\n<!-- ============ FAQ ============ -->\n<section class=\"mt-8 report-card rounded-sm p-6 sm:p-10\" aria-label=\"Frequently asked questions\">\n  <p class=\"text-[11px] tracking-[0.25em] uppercase font-bold mb-2\" style=\"color:#B91C1C;\">Registrar&rsquo;s Office</p>\n  <h2 class=\"serif text-2xl font-bold mb-6\" style=\"color:#1E3A8A;\">Frequently Asked Questions</h2>\n  <div class=\"space-y-3\">\n    <details class=\"faq-item border rounded-sm\" style=\"border-color:#1E3A8A;\">\n      <summary class=\"serif font-bold px-4 py-3 flex justify-between items-center gap-2\" style=\"color:#1E3A8A;\">How is GPA calculated from course grades and credits? <span aria-hidden=\"true\">+</span></summary>\n      <p class=\"text-sm px-4 pb-4 leading-6\" style=\"color:#374151;\">Convert each letter grade to grade points (for example, A = 4.0, B+ = 3.3 on the US scale), multiply by the course&rsquo;s credits to get quality points, add up all quality points, and divide by total credits. So a 4-credit A (16.0 points) plus a 3-credit B (9.0 points) gives 25.0 &divide; 7 = 3.57. Credits act as weights, which is why heavy courses move your GPA more.</p>\n    </details>\n    <details class=\"faq-item border rounded-sm\" style=\"border-color:#1E3A8A;\">\n      <summary class=\"serif font-bold px-4 py-3 flex justify-between items-center gap-2\" style=\"color:#1E3A8A;\">What is the difference between GPA and CGPA? <span aria-hidden=\"true\">+</span></summary>\n      <p class=\"text-sm px-4 pb-4 leading-6\" style=\"color:#374151;\">GPA (or SGPA) covers one semester; CGPA covers your entire program. Crucially, CGPA is total quality points across all semesters divided by total credits \u2014 not the average of your semester GPAs. Averaging SGPAs directly gives the wrong answer whenever semesters have different credit loads.</p>\n    </details>\n    <details class=\"faq-item border rounded-sm\" style=\"border-color:#1E3A8A;\">\n      <summary class=\"serif font-bold px-4 py-3 flex justify-between items-center gap-2\" style=\"color:#1E3A8A;\">How do I convert my Indian 10-point CGPA to a US 4.0 GPA? <span aria-hidden=\"true\">+</span></summary>\n      <p class=\"text-sm px-4 pb-4 leading-6\" style=\"color:#374151;\">There is no single official formula. A common planning estimate goes through letter grades: map your Indian grade (O, A+, A, B+ &hellip;) to its US letter equivalent and read off the 4.0 points. Many evaluators also consider your institution and class rank, so treat any conversion as an estimate. GradeAxis&rsquo;s cross-scale converter uses the letter-equivalent method.</p>\n    </details>\n    <details class=\"faq-item border rounded-sm\" style=\"border-color:#1E3A8A;\">\n      <summary class=\"serif font-bold px-4 py-3 flex justify-between items-center gap-2\" style=\"color:#1E3A8A;\">How does the German 1.0\u20135.0 grading scale work? <span aria-hidden=\"true\">+</span></summary>\n      <p class=\"text-sm px-4 pb-4 leading-6\" style=\"color:#374151;\">It is inverted: 1.0 is the best grade (sehr gut) and 5.0 means fail. The ladder runs 1.0, 1.3, 1.7, 2.0, 2.3, 2.7, 3.0, 3.3, 3.7, 4.0, then 5.0 for failure. Averages are computed the same way as any GPA, but lower is better \u2014 a 1.5 average is excellent. German universities often convert foreign grades with the modified Bavarian formula.</p>\n    </details>\n    <details class=\"faq-item border rounded-sm\" style=\"border-color:#1E3A8A;\">\n      <summary class=\"serif font-bold px-4 py-3 flex justify-between items-center gap-2\" style=\"color:#1E3A8A;\">What is a weighted GPA, and how do Honors and AP classes affect it? <span aria-hidden=\"true\">+</span></summary>\n      <p class=\"text-sm px-4 pb-4 leading-6\" style=\"color:#374151;\">A weighted GPA adds a rigor bonus: typically +0.5 for Honors and +1.0 for AP/IB courses, so an A in AP Calculus counts as 5.0 instead of 4.0. That is why weighted GPAs can exceed 4.0. Policies vary by school, and an F still earns 0 points even in a weighted course. On the German scale the bonus is mirrored (&minus;0.5 / &minus;1.0) because lower is better.</p>\n    </details>\n    <details class=\"faq-item border rounded-sm\" style=\"border-color:#1E3A8A;\">\n      <summary class=\"serif font-bold px-4 py-3 flex justify-between items-center gap-2\" style=\"color:#1E3A8A;\">What grades do I need to reach my target CGPA? <span aria-hidden=\"true\">+</span></summary>\n      <p class=\"text-sm px-4 pb-4 leading-6\" style=\"color:#374151;\">Use the formula: required average = (target &times; total credits &minus; current CGPA &times; completed credits) &divide; remaining credits. If the result is above your scale&rsquo;s maximum (or below 1.0 on the German scale), the target is mathematically impossible. GradeAxis&rsquo;s planner runs this math and gives you a plain-English feasibility verdict.</p>\n    </details>\n  </div>\n</section>\n</div>\n\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    {\n      \"@type\": \"Question\",\n      \"name\": \"How is GPA calculated from course grades and credits?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Convert each letter grade to grade points (A = 4.0, B+ = 3.3 on the US scale), multiply by the course's credits to get quality points, sum all quality points, and divide by total credits. Credits act as weights, so heavy courses move your GPA more.\" }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"What is the difference between GPA and CGPA?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"GPA (SGPA) covers one semester; CGPA covers the entire program. CGPA equals total quality points across all semesters divided by total credits \u2014 not the average of semester GPAs, which gives the wrong answer when semesters differ in credit load.\" }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"How do I convert my Indian 10-point CGPA to a US 4.0 GPA?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"There is no single official formula. A common planning estimate maps the Indian grade (O, A+, A, B+...) to its US letter equivalent and reads off the 4.0 points. Evaluators also consider institution and rank, so treat conversions as estimates.\" }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"How does the German 1.0\u20135.0 grading scale work?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"It is inverted: 1.0 is the best grade (sehr gut) and 5.0 means fail. Grades run 1.0, 1.3, 1.7, 2.0, 2.3, 2.7, 3.0, 3.3, 3.7, 4.0, then 5.0. Averages are computed normally, but lower is better \u2014 a 1.5 average is excellent.\" }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"What is a weighted GPA, and how do Honors and AP classes affect it?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"A weighted GPA adds a rigor bonus \u2014 typically +0.5 for Honors and +1.0 for AP/IB \u2014 so an A in AP Calculus counts as 5.0. Policies vary by school, and an F still earns 0 points. On the German scale the bonus is mirrored because lower is better.\" }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"What grades do I need to reach my target CGPA?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Required average = (target x total credits - current CGPA x completed credits) / remaining credits. If the result exceeds the scale maximum (or drops below 1.0 on the German scale), the target is mathematically impossible.\" }\n    }\n  ]\n}\n</script>\n\n<footer class=\"no-print border-t-[3px] border-double mt-4\" style=\"border-color:#1E3A8A; background:#1E3A8A;\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 py-8 flex flex-col sm:flex-row items-center justify-between gap-3\">\n    <p class=\"serif text-lg font-bold\" style=\"color:#F7F4EA;\">Grade<span style=\"color:#F87171;\">Axis</span> <span class=\"text-xs font-sans font-normal\" style=\"color:#D1D5DB;\">\u2014 free GPA &amp; CGPA calculator</span></p>\n    <div class=\"flex items-center gap-5 text-sm font-semibold\" style=\"color:#F7F4EA;\">\n      <a href=\"#top\" class=\"hover:underline\">Home</a>\n      <a href=\"https://fixoraa.tech\" class=\"hover:underline\">More Tools</a>\n    </div>\n  </div>\n  <p class=\"text-center text-[11px] pb-6\" style=\"color:#9CA3AF;\">Your grades never leave your browser. Made for students everywhere.</p>\n<p class=\"fx-credit\" style=\"text-align:center;font-size:12.5px;opacity:.62;margin:10px auto 2px;letter-spacing:.01em\">Made by <a href=\"https://fixoraa.tech\" target=\"_blank\" rel=\"noopener\" style=\"color:inherit;font-weight:700;text-decoration:underline;text-underline-offset:2px\">Fixoraa</a></p>\n</footer>\n\n<!-- ============ PURE CALCULATION LOGIC (extracted by tests) ============ -->\n<script>\n/*__PURE_START__*/\n'use strict';\n\nvar HONORS_BUMP = 0.5;\nvar AP_BUMP = 1.0;\n\nvar SCALES = {\n  '4.0': {\n    name: '4.0 (US)', max: 4.0, min: 0, lowerBetter: false,\n    grades: [['A',4.0],['A-',3.7],['B+',3.3],['B',3.0],['B-',2.7],['C+',2.3],['C',2.0],['C-',1.7],['D+',1.3],['D',1.0],['F',0]]\n  },\n  '5.0': {\n    name: '5.0 Scale', max: 5.0, min: 0, lowerBetter: false,\n    grades: [['A',5.0],['A-',4.7],['B+',4.3],['B',4.0],['B-',3.7],['C+',3.3],['C',3.0],['C-',2.7],['D+',2.3],['D',2.0],['F',0]]\n  },\n  '10.0': {\n    name: '10.0 (Indian CGPA)', max: 10, min: 0, lowerBetter: false,\n    grades: [['O',10],['A+',9],['A',8],['B+',7],['B',6],['C',5],['D',4],['F',0]]\n  },\n  'german': {\n    name: 'German 1.0\u20135.0', max: 5.0, min: 1.0, lowerBetter: true,\n    grades: [['A',1.0],['A-',1.3],['B+',1.7],['B',2.0],['B-',2.3],['C+',2.7],['C',3.0],['C-',3.3],['D+',3.7],['D',4.0],['F',5.0]]\n  }\n};\n\n// Percent -> letter bands (cutoff = minimum percent for that letter)\nvar PERCENT_BANDS = [['A',93],['A-',90],['B+',87],['B',83],['B-',80],['C+',77],['C',73],['C-',70],['D+',67],['D',65],['F',0]];\nvar PERCENT_MIDS  = { 'A':96.5,'A-':91,'B+':88,'B':84.5,'B-':81,'C+':78,'C':74.5,'C-':71,'D+':68,'D':65.5,'F':32.5 };\nvar GERMAN_PERCENT_BANDS = [['A',95],['A-',90],['B+',85],['B',80],['B-',75],['C+',70],['C',65],['C-',60],['D+',55],['D',50],['F',0]];\nvar GERMAN_PERCENT_MIDS  = { 'A':97.5,'A-':92,'B+':87.5,'B':82.5,'B-':77.5,'C+':72.5,'C':67.5,'C-':62,'D+':57.5,'D':52.5,'F':25 };\nvar TEN_PERCENT_BANDS = [['O',90],['A+',80],['A',70],['B+',60],['B',50],['C',40],['D',35],['F',0]];\n\nfunction scaleIds() { return Object.keys(SCALES); }\nfunction scaleInfo(id) { return SCALES[id] || SCALES['4.0']; }\n\nfunction letterToPoints(scale, letter) {\n  var s = scaleInfo(scale);\n  for (var i = 0; i < s.grades.length; i++) {\n    if (s.grades[i][0] === letter) return s.grades[i][1];\n  }\n  return NaN;\n}\n\nfunction gpaToLetter(scale, points) {\n  if (!isFinite(points)) return '';\n  var s = scaleInfo(scale), best = '', bd = Infinity;\n  for (var i = 0; i < s.grades.length; i++) {\n    var d = Math.abs(s.grades[i][1] - points);\n    if (d < bd) { bd = d; best = s.grades[i][0]; }\n  }\n  return best;\n}\n\nfunction weightedBump(scale, type) {\n  var s = scaleInfo(scale);\n  if (type === 'honors') return s.lowerBetter ? -HONORS_BUMP : HONORS_BUMP;\n  if (type === 'ap') return s.lowerBetter ? -AP_BUMP : AP_BUMP;\n  return 0;\n}\n\n// Grade points for one course: gradePoint(scale, letter, courseType, weighted)\n// courseType: 'regular' | 'honors' | 'ap'\nfunction gradePoint(scale, letter, type, weighted) {\n  var s = scaleInfo(scale);\n  var base = letterToPoints(scale, letter);\n  if (!isFinite(base)) return NaN;\n  if (!weighted) return base;\n  var isFail = s.lowerBetter ? base >= s.max - 1e-9 : base <= s.min + 1e-9;\n  var v = isFail ? base : base + weightedBump(scale, type || 'regular');\n  var hi = s.lowerBetter ? s.max : (scale === '4.0' ? 5.0 : s.max); // weighted 4.0 ceiling is 5.0\n  return Math.min(hi, Math.max(s.min, v));\n}\n\n// courses: [{credits, grade, type}]  -> {gpa, points, credits, courses}\nfunction semesterGPA(courses, scale, weighted) {\n  var pts = 0, cr = 0, n = 0;\n  var list = courses || [];\n  for (var i = 0; i < list.length; i++) {\n    var c = list[i] || {};\n    var gp = gradePoint(scale, c.grade, c.type, weighted);\n    var ch = Number(c.credits);\n    if (!isFinite(gp) || !isFinite(ch) || ch <= 0) continue;\n    pts += gp * ch; cr += ch; n++;\n  }\n  if (cr <= 0) return { gpa: NaN, points: 0, credits: 0, courses: 0 };\n  return { gpa: pts / cr, points: pts, credits: cr, courses: n };\n}\n\n// semesters: [{points, credits}] -> {cgpa, points, credits}\nfunction cumulativeCGPA(semesters) {\n  var pts = 0, cr = 0;\n  var list = semesters || [];\n  for (var i = 0; i < list.length; i++) {\n    var p = Number(list[i].points), c = Number(list[i].credits);\n    if (isFinite(p) && isFinite(c) && c > 0) { pts += p; cr += c; }\n  }\n  if (cr <= 0) return { cgpa: NaN, points: 0, credits: 0 };\n  return { cgpa: pts / cr, points: pts, credits: cr };\n}\n\n// Planner math: required = (target*totalCredits - earnedPoints) / remainingCredits\nfunction planRequired(currentGPA, earnedCredits, targetGPA, remainingCredits) {\n  var c = Number(currentGPA), e = Number(earnedCredits),\n      t = Number(targetGPA), r = Number(remainingCredits);\n  if (!isFinite(c) || !isFinite(e) || !isFinite(t) || !isFinite(r) || e < 0 || r <= 0)\n    return { required: NaN, ok: false };\n  return { required: (t * (e + r) - c * e) / r, ok: true };\n}\n\nfunction plannerBounds(scale, weighted) {\n  var s = scaleInfo(scale);\n  if (s.lowerBetter) return { best: s.min, worst: s.max };\n  return { best: (weighted && scale === '4.0') ? 5.0 : s.max, worst: s.min };\n}\n\nfunction planVerdict(scale, required, currentGPA, weighted) {\n  var s = scaleInfo(scale), b = plannerBounds(scale, weighted);\n  if (!isFinite(required))\n    return { label: 'Enter valid numbers', tone: 'neutral', detail: 'Fill in all four planner fields with valid numbers.' };\n  var c = Number(currentGPA);\n  var impossible = s.lowerBetter ? required < b.best - 1e-9 : required > b.best + 1e-9;\n  if (impossible) return s.lowerBetter\n    ? { label: 'Not possible', tone: 'bad', detail: 'Even a perfect 1.0 in every remaining credit is not enough \u2014 and on the German scale, lower is better.' }\n    : { label: 'Not possible', tone: 'bad', detail: 'Even perfect grades in every remaining credit fall short. Lower the target or plan more credits.' };\n  if (s.lowerBetter) {\n    if (required <= 1.3) return { label: 'Stretch \u2014 near-perfect marks needed', tone: 'warn', detail: 'You need close to 1.0 (sehr gut) across all remaining credits.' };\n    if (isFinite(c) && required < c - 0.3) return { label: 'Achievable \u2014 improve on your average', tone: 'good', detail: 'You need a better (lower) average than your current one.' };\n    return { label: 'Within reach', tone: 'good', detail: 'Your current pace is enough to hit this target.' };\n  }\n  if (required >= b.best - 0.3) return { label: 'Stretch \u2014 nearly all top grades needed', tone: 'warn', detail: 'Almost every remaining course must be an A (or its weighted equivalent).' };\n  if (isFinite(c) && required > c + 0.3) return { label: 'Achievable \u2014 aim above your average', tone: 'good', detail: 'You need grades above your current average in the remaining credits.' };\n  return { label: 'Within reach', tone: 'good', detail: 'Keep up your current pace and the target is yours.' };\n}\n\nfunction percentToLetter(percent, scale) {\n  if (!isFinite(percent) || percent < 0) return '';\n  var bands = scale === 'german' ? GERMAN_PERCENT_BANDS : (scale === '10.0' ? TEN_PERCENT_BANDS : PERCENT_BANDS);\n  for (var i = 0; i < bands.length; i++) {\n    if (percent >= bands[i][1]) return bands[i][0];\n  }\n  return 'F';\n}\n\nfunction percentToGPA(percent, scale) {\n  if (!isFinite(percent) || percent < 0) return NaN;\n  if (scale === '10.0') return Math.min(10, Math.max(0, percent / 10)); // %/10 convention\n  return letterToPoints(scale, percentToLetter(percent, scale));\n}\n\nfunction gpaToPercent(gpa, scale) {\n  if (!isFinite(gpa)) return NaN;\n  if (scale === '10.0') return Math.min(100, Math.max(0, gpa / 10 * 100));\n  var l = gpaToLetter(scale, gpa);\n  var mids = scale === 'german' ? GERMAN_PERCENT_MIDS : PERCENT_MIDS;\n  return mids[l] !== undefined ? mids[l] : NaN;\n}\n\n// Cross-scale conversion through the canonical letter grade\nfunction convertScale(points, fromScale, toScale) {\n  if (!isFinite(points)) return NaN;\n  if (fromScale === toScale) return points;\n  var l = gpaToLetter(fromScale, points);\n  if (!l) return NaN;\n  return letterToPoints(toScale, l);\n}\n\n// Semicircle gauge SVG for a GPA value on a scale\nfunction gpaDialSVG(gpa, scale) {\n  var s = scaleInfo(scale);\n  var W = 220, H = 132, cx = 110, cy = 106, r = 82;\n  var frac = isFinite(gpa)\n    ? (s.lowerBetter ? (s.max - gpa) / (s.max - s.min) : (gpa - s.min) / (s.max - s.min))\n    : 0;\n  var f = Math.min(1, Math.max(0, frac));\n  var a1 = Math.PI * (1 - f);\n  var x1 = (cx + r * Math.cos(a1)).toFixed(1), y1 = (cy + r * Math.sin(a1)).toFixed(1);\n  var large = f > 0.5 ? 1 : 0;\n  var label = isFinite(gpa) ? gpa.toFixed(2) : '\u2014';\n  var fg = s.lowerBetter ? '#B91C1C' : '#1E3A8A';\n  return '<svg viewBox=\"0 0 ' + W + ' ' + H + '\" width=\"220\" height=\"132\" role=\"img\" aria-label=\"GPA dial\">' +\n    '<path d=\"M ' + (cx - r) + ' ' + cy + ' A ' + r + ' ' + r + ' 0 0 1 ' + (cx + r) + ' ' + cy + '\" fill=\"none\" stroke=\"#E5E0D0\" stroke-width=\"14\" stroke-linecap=\"round\"/>' +\n    '<path d=\"M ' + (cx - r) + ' ' + cy + ' A ' + r + ' ' + r + ' 0 ' + large + ' 1 ' + x1 + ' ' + y1 + '\" fill=\"none\" stroke=\"' + fg + '\" stroke-width=\"14\" stroke-linecap=\"round\"/>' +\n    '<text x=\"' + cx + '\" y=\"' + (cy - 12) + '\" text-anchor=\"middle\" font-family=\"Georgia, serif\" font-size=\"34\" font-weight=\"bold\" fill=\"#1F2937\">' + label + '</text>' +\n    '<text x=\"' + cx + '\" y=\"' + (cy + 14) + '\" text-anchor=\"middle\" font-family=\"Georgia, serif\" font-size=\"12\" font-style=\"italic\" fill=\"#6B7280\">' + s.name + ' scale</text>' +\n    '</svg>';\n}\n\n// Ledger helpers\nfunction saveSemester(list, entry, maxN) {\n  maxN = maxN || 24;\n  return [entry].concat(list || []).slice(0, maxN);\n}\nfunction ledgerToCSV(entries) {\n  var head = 'Semester,Date,Scale,Weighted,GPA,Credits,Quality Points';\n  var rows = (entries || []).map(function (e) {\n    function q(v) { return '\"' + String(v == null ? '' : v).replace(/\"/g, '\"\"') + '\"'; }\n    return [q(e.name), q(e.date), q(e.scale), q(e.weighted ? 'yes' : 'no'),\n            q(fmt2(e.gpa)), q(e.credits), q(fmt2(e.points))].join(',');\n  });\n  return [head].concat(rows).join('\\n');\n}\nfunction fmt2(x) { return isFinite(x) ? Number(x).toFixed(2) : ''; }\n/*__PURE_END__*/\n</script>\n\n<!-- ============ APP WIRING (DOM) ============ -->\n<script>\n(function () {\n  'use strict';\n  function $(id) { return document.getElementById(id); }\n  var LEDGER_KEY = 'gradeaxis-semesters-v1';\n\n  var state = { scale: '4.0', weighted: false, semesters: loadLedger() };\n  var courses = [\n    { name: 'Mathematics', credits: 4, grade: 'A',  type: 'regular' },\n    { name: 'English Literature', credits: 3, grade: 'B+', type: 'regular' },\n    { name: 'Physics', credits: 4, grade: 'B',  type: 'honors' },\n    { name: 'History', credits: 3, grade: 'A-', type: 'ap' }\n  ];\n\n  var SCALE_NOTES = {\n    '4.0': 'US standard: A = 4.0 \u2026 F = 0. Weighted mode adds +0.5 (Honors) / +1.0 (AP/IB), ceiling 5.0.',\n    '5.0': 'Five-point scale: A = 5.0 \u2026 F = 0. Used by many high schools and universities worldwide.',\n    '10.0': 'Indian CGPA style: O = 10, A+ = 9, A = 8, B+ = 7, B = 6, C = 5, D = 4, F = 0.',\n    'german': 'Inverted scale: 1.0 is best, 5.0 is fail. Weighted mode subtracts 0.5 / 1.0 (floor 1.0).'\n  };\n  var TYPE_LABELS = { regular: 'Regular', honors: 'Honors', ap: 'AP / IB' };\n\n  function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;'); }\n\n  function loadLedger() {\n    try { var v = JSON.parse(localStorage.getItem(LEDGER_KEY)); return Array.isArray(v) ? v : []; }\n    catch (e) { return []; }\n  }\n  function persistLedger() {\n    try { localStorage.setItem(LEDGER_KEY, JSON.stringify(state.semesters)); } catch (e) {}\n  }\n\n  // ---------- scale tabs ----------\n  var tabs = document.querySelectorAll('#scaleTabs button');\n  tabs.forEach(function (btn) {\n    btn.addEventListener('click', function () {\n      var oldScale = state.scale, nu = btn.getAttribute('data-scale');\n      if (oldScale === nu) return;\n      var oldGrades = scaleInfo(oldScale).grades, nuGrades = scaleInfo(nu).grades;\n      courses.forEach(function (c) {\n        var idx = -1;\n        for (var i = 0; i < oldGrades.length; i++) if (oldGrades[i][0] === c.grade) { idx = i; break; }\n        c.grade = idx >= 0 ? nuGrades[Math.min(idx, nuGrades.length - 1)][0] : nuGrades[0][0];\n      });\n      state.scale = nu;\n      tabs.forEach(function (b) { b.classList.toggle('active', b === btn); });\n      $('scaleNote').textContent = SCALE_NOTES[nu];\n      buildRows(); renderAll();\n    });\n  });\n  $('scaleNote').textContent = SCALE_NOTES['4.0'];\n  $('weightedToggle').addEventListener('change', function (e) {\n    state.weighted = e.target.checked;\n    buildRows(); renderAll();\n  });\n\n  // ---------- course rows ----------\n  function gradeOptions(sel) {\n    return scaleInfo(state.scale).grades.map(function (g) {\n      return '<option value=\"' + g[0] + '\"' + (g[0] === sel ? ' selected' : '') + '>' + g[0] + '</option>';\n    }).join('');\n  }\n  function typeOptions(sel) {\n    return ['regular', 'honors', 'ap'].map(function (t) {\n      return '<option value=\"' + t + '\"' + (t === sel ? ' selected' : '') + '>' + TYPE_LABELS[t] + '</option>';\n    }).join('');\n  }\n  function buildRows() {\n    var box = $('courseRows'); box.innerHTML = '';\n    courses.forEach(function (c, i) {\n      var row = document.createElement('div');\n      row.className = 'grid grid-cols-2 md:grid-cols-12 gap-2 items-end border rounded-sm p-2';\n      row.style.borderColor = '#E5E0D0'; row.style.background = '#fff';\n      row.innerHTML =\n        '<label class=\"col-span-2 md:col-span-4 block\"><span class=\"md:hidden text-[10px] font-bold uppercase\" style=\"color:#1E3A8A;\">Course</span>' +\n          '<input type=\"text\" data-f=\"name\" value=\"' + esc(c.name) + '\" maxlength=\"60\" placeholder=\"Course name\" class=\"w-full border rounded-sm px-2 py-1.5 text-sm\" style=\"border-color:#CBD5E1;\"></label>' +\n        '<label class=\"col-span-1 md:col-span-2 block\"><span class=\"md:hidden text-[10px] font-bold uppercase\" style=\"color:#1E3A8A;\">Credits</span>' +\n          '<input type=\"number\" data-f=\"credits\" value=\"' + esc(c.credits) + '\" min=\"0\" max=\"12\" step=\"0.5\" class=\"w-full border rounded-sm px-2 py-1.5 text-sm\" style=\"border-color:#CBD5E1;\"></label>' +\n        '<label class=\"col-span-1 md:col-span-2 block\"><span class=\"md:hidden text-[10px] font-bold uppercase\" style=\"color:#1E3A8A;\">Grade</span>' +\n          '<select data-f=\"grade\" class=\"w-full border rounded-sm px-2 py-1.5 text-sm font-semibold\" style=\"border-color:#CBD5E1;\">' + gradeOptions(c.grade) + '</select></label>' +\n        '<label class=\"col-span-1 md:col-span-2 block\"><span class=\"md:hidden text-[10px] font-bold uppercase\" style=\"color:#1E3A8A;\">Level</span>' +\n          '<select data-f=\"type\" class=\"w-full border rounded-sm px-2 py-1.5 text-sm\" style=\"border-color:#CBD5E1;\">' + typeOptions(c.type) + '</select></label>' +\n        '<div class=\"col-span-1 md:col-span-1 md:text-right\"><span class=\"md:hidden text-[10px] font-bold uppercase\" style=\"color:#1E3A8A;\">Pts</span>' +\n          '<p data-f=\"points\" class=\"serif font-bold text-sm\" style=\"color:#1E3A8A;\"></p></div>' +\n        '<div class=\"col-span-2 md:col-span-1 md:text-right\"><button type=\"button\" data-f=\"remove\" class=\"text-xs font-bold px-2 py-1.5 rounded-sm border\" style=\"border-color:#FCA5A5; color:#B91C1C;\" aria-label=\"Remove course\">&times; Remove</button></div>';\n      row.addEventListener('input', function (e) {\n        var f = e.target.getAttribute('data-f');\n        if (f === 'name') c.name = e.target.value;\n        else if (f === 'credits') c.credits = e.target.value === '' ? '' : Number(e.target.value);\n        else if (f === 'grade') c.grade = e.target.value;\n        else if (f === 'type') c.type = e.target.value;\n        renderAll();\n      });\n      row.querySelector('[data-f=\"remove\"]').addEventListener('click', function () {\n        courses.splice(i, 1);\n        if (!courses.length) courses.push({ name: '', credits: '', grade: scaleInfo(state.scale).grades[0][0], type: 'regular' });\n        buildRows(); renderAll();\n      });\n      box.appendChild(row);\n    });\n  }\n  $('addCourse').addEventListener('click', function () {\n    courses.push({ name: '', credits: '', grade: scaleInfo(state.scale).grades[0][0], type: 'regular' });\n    buildRows(); renderAll();\n    var rows = $('courseRows').children;\n    var inp = rows[rows.length - 1].querySelector('[data-f=\"name\"]');\n    if (inp) inp.focus();\n  });\n  $('clearCourses').addEventListener('click', function () {\n    courses = [{ name: '', credits: '', grade: scaleInfo(state.scale).grades[0][0], type: 'regular' }];\n    buildRows(); renderAll();\n  });\n\n  // ---------- results ----------\n  function currentResult() { return semesterGPA(courses, state.scale, state.weighted); }\n  function renderResults() {\n    var r = currentResult();\n    $('gpaDial').innerHTML = gpaDialSVG(r.gpa, state.scale);\n    $('statGpa').textContent = isFinite(r.gpa) ? r.gpa.toFixed(2) : '\u2014';\n    $('statLetter').textContent = isFinite(r.gpa) ? gpaToLetter(state.scale, r.gpa) : '\u2014';\n    $('statCredits').textContent = r.courses ? r.credits : '\u2014';\n    $('statPoints').textContent = r.courses ? r.points.toFixed(1) : '\u2014';\n    var rows = $('courseRows').children;\n    courses.forEach(function (c, i) {\n      var cell = rows[i] && rows[i].querySelector('[data-f=\"points\"]');\n      if (cell) {\n        var gp = gradePoint(state.scale, c.grade, c.type, state.weighted);\n        cell.textContent = isFinite(gp) ? gp.toFixed(1) : '\u2013';\n      }\n    });\n  }\n\n  // ---------- ledger ----------\n  $('saveSemester').addEventListener('click', function () {\n    var name = $('semName').value.trim(), r = currentResult(), msg = $('ledgerMsg');\n    msg.textContent = '';\n    if (!name) { msg.textContent = 'Please give this semester a name first.'; return; }\n    if (!isFinite(r.gpa)) { msg.textContent = 'Add at least one valid course (grade + credits) before saving.'; return; }\n    state.semesters = saveSemester(state.semesters, {\n      id: Date.now(), name: name, date: new Date().toISOString().slice(0, 10),\n      scale: state.scale, weighted: state.weighted,\n      gpa: Number(r.gpa.toFixed(2)), credits: r.credits, points: Number(r.points.toFixed(2))\n    });\n    persistLedger();\n    $('semName').value = '';\n    msg.style.color = '#166534'; msg.textContent = 'Saved \u201c' + name + '\u201d to your ledger.';\n    setTimeout(function () { msg.style.color = '#B91C1C'; msg.textContent = ''; }, 3000);\n    renderLedger();\n  });\n  $('clearLedger').addEventListener('click', function () {\n    if (!state.semesters.length) return;\n    if (confirm('Delete all saved semesters? This cannot be undone.')) {\n      state.semesters = []; persistLedger(); renderLedger();\n    }\n  });\n  $('downloadCsv').addEventListener('click', function () {\n    if (!state.semesters.length) { alert('Your ledger is empty \u2014 save a semester first.'); return; }\n    var blob = new Blob([ledgerToCSV(state.semesters)], { type: 'text/csv;charset=utf-8' });\n    var a = document.createElement('a');\n    a.href = URL.createObjectURL(blob); a.download = 'gradeaxis-ledger.csv';\n    document.body.appendChild(a); a.click();\n    setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 500);\n  });\n  $('printReport').addEventListener('click', function () { window.print(); });\n\n  function renderLedger() {\n    var body = $('ledgerBody'); body.innerHTML = '';\n    if (!state.semesters.length) {\n      body.innerHTML = '<tr><td colspan=\"6\" class=\"px-3 py-6 text-center text-sm italic\" style=\"color:#9CA3AF;\">No semesters saved yet \u2014 your ledger awaits its first entry.</td></tr>';\n    }\n    state.semesters.forEach(function (s) {\n      var tr = document.createElement('tr');\n      tr.className = 'border-t'; tr.style.borderColor = '#E5E0D0';\n      tr.innerHTML =\n        '<td class=\"px-3 py-2 font-semibold\">' + esc(s.name) + '<span class=\"block text-[11px] font-normal\" style=\"color:#9CA3AF;\">' + esc(s.date) + '</span></td>' +\n        '<td class=\"px-3 py-2 text-xs\">' + esc(scaleInfo(s.scale).name) + (s.weighted ? ' \u00b7 W' : '') + '</td>' +\n        '<td class=\"px-3 py-2 text-right serif font-bold\" style=\"color:#1E3A8A;\">' + fmt2(s.gpa) + '</td>' +\n        '<td class=\"px-3 py-2 text-right\">' + esc(s.credits) + '</td>' +\n        '<td class=\"px-3 py-2 text-right\">' + fmt2(s.points) + '</td>' +\n        '<td class=\"px-3 py-2 text-right\"><button type=\"button\" class=\"text-xs font-bold px-2 py-1 rounded-sm border\" style=\"border-color:#FCA5A5; color:#B91C1C;\" aria-label=\"Delete semester\">Delete</button></td>';\n      tr.querySelector('button').addEventListener('click', function () {\n        state.semesters = state.semesters.filter(function (x) { return x.id !== s.id; });\n        persistLedger(); renderLedger();\n      });\n      body.appendChild(tr);\n    });\n    var cum = cumulativeCGPA(state.semesters);\n    $('statCgpa').textContent = isFinite(cum.cgpa) ? cum.cgpa.toFixed(2) : '\u2014';\n    $('statCgpaSub').textContent = state.semesters.length\n      ? state.semesters.length + ' semester' + (state.semesters.length > 1 ? 's' : '') + ' \u00b7 ' + cum.credits + ' credits'\n      : 'Save a semester to begin';\n    var r = currentResult();\n    var proj = cumulativeCGPA(state.semesters.concat(isFinite(r.gpa) ? [{ points: r.points, credits: r.credits }] : []));\n    $('statProj').textContent = isFinite(proj.cgpa) ? proj.cgpa.toFixed(2) : '\u2014';\n    $('statProjSub').textContent = isFinite(proj.cgpa) && isFinite(r.gpa)\n      ? 'Includes current worksheet (' + r.gpa.toFixed(2) + ')'\n      : 'Add courses above to preview';\n  }\n\n  // ---------- planner ----------\n  $('planBtn').addEventListener('click', function () {\n    var cur = parseFloat($('plCur').value), earned = parseFloat($('plEarned').value),\n        target = parseFloat($('plTarget').value), rem = parseFloat($('plRem').value);\n    var pr = planRequired(cur, earned, target, rem);\n    var box = $('planResult'); box.classList.remove('hidden');\n    if (!pr.ok) {\n      $('planReq').textContent = '\u2014'; $('planLetter').textContent = '';\n      setVerdict({ label: 'Enter valid numbers', tone: 'neutral', detail: 'Fill in all four planner fields with valid numbers.' });\n      return;\n    }\n    var v = planVerdict(state.scale, pr.required, cur, state.weighted);\n    var b = plannerBounds(state.scale, state.weighted);\n    var inRange = scaleInfo(state.scale).lowerBetter\n      ? pr.required >= b.best - 1e-9 : pr.required <= b.best + 1e-9;\n    $('planReq').textContent = pr.required.toFixed(2);\n    $('planLetter').textContent = inRange ? '\u2248 ' + gpaToLetter(state.scale, pr.required) : '';\n    setVerdict(v);\n  });\n  function setVerdict(v) {\n    var el = $('planVerdict');\n    el.textContent = v.label;\n    var colors = { bad: ['#FEE2E2', '#B91C1C'], warn: ['#FEF3C7', '#92400E'], good: ['#DCFCE7', '#166534'], neutral: ['#F3F4F6', '#4B5563'] };\n    var c = colors[v.tone] || colors.neutral;\n    el.style.background = c[0]; el.style.color = c[1];\n    $('planDetail').textContent = v.detail + ' (Scale: ' + scaleInfo(state.scale).name + (state.weighted ? ', weighted' : '') + '.)';\n  }\n\n  // ---------- conversion tables ----------\n  function renderConvTables() {\n    var box = $('convTables'); box.innerHTML = '';\n    var defs = [\n      { title: '4.0 (US) scale', bands: PERCENT_BANDS, scale: '4.0' },\n      { title: '10.0 (Indian CGPA)', bands: TEN_PERCENT_BANDS, scale: '10.0' },\n      { title: 'German 1.0\u20135.0', bands: GERMAN_PERCENT_BANDS, scale: 'german' }\n    ];\n    defs.forEach(function (d) {\n      var rows = d.bands.map(function (b) {\n        return '<tr class=\"border-t\" style=\"border-color:#E5E0D0;\"><td class=\"px-2 py-1.5\">' + b[1] + '+%</td>' +\n          '<td class=\"px-2 py-1.5 font-bold\" style=\"color:#1E3A8A;\">' + b[0] + '</td>' +\n          '<td class=\"px-2 py-1.5 text-right serif font-bold\" style=\"color:#B91C1C;\">' + letterToPoints(d.scale, b[0]).toFixed(1) + '</td></tr>';\n      }).join('');\n      var div = document.createElement('div');\n      div.className = 'border-2 rounded-sm overflow-hidden'; div.style.borderColor = '#1E3A8A';\n      div.innerHTML = '<p class=\"serif text-sm font-bold px-3 py-2\" style=\"background:#1E3A8A; color:#F7F4EA;\">' + d.title + '</p>' +\n        '<table class=\"w-full text-xs\"><thead><tr class=\"text-left text-[10px] uppercase tracking-wider\" style=\"color:#6B7280;\">' +\n        '<th class=\"px-2 py-1.5\">Percent</th><th class=\"px-2 py-1.5\">Letter</th><th class=\"px-2 py-1.5 text-right\">Points</th></tr></thead>' +\n        '<tbody>' + rows + '</tbody></table>';\n      box.appendChild(div);\n    });\n  }\n\n  function renderAll() { renderResults(); renderLedger(); }\n  buildRows(); renderConvTables(); renderAll();\n})();\n</script>\n</body>\n</html>\n";
export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname !== "/" && url.pathname !== "/index.html") {
      return new Response("Not found", { status: 404 });
    }
    return new Response(HTML, {
      headers: { "content-type": "text/html;charset=UTF-8" }
    });
  }
};